```js
function sweptCollision(ball, prevX, prevY, brick) {
  // Expand the brick by the ball radius.
  const left = brick.x - ball.r, right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r, bottom = brick.y + brick.h + ball.r;
  // Does the segment (prevX,prevY)->(ball.x,ball.y) intersect the expanded rect?
  // Slab method for segment-AABB.
  let tMin = 0, tMax = 1;
  const dx = ball.x - prevX, dy = ball.y - prevY;
  // x slab
  if (Math.abs(dx) < 1e-12) {
    if (prevX < left || prevX > right) return null;
  } else {
    let t1 = (left - prevX) / dx, t2 = (right - prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1); tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }
  // y slab
  if (Math.abs(dy) < 1e-12) {
    if (prevY < top || prevY > bottom) return null;
  } else {
    let t1 = (top - prevY) / dy, t2 = (bottom - prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tMin = Math.max(tMin, t1); tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }
  return tMin; // time of first contact along the segment
