// Returns the first contact between the ball's swept segment (previous to
// current position) and the brick expanded by the ball radius, as a slab
// test (segment vs AABB). The face is the expanded-rect edge crossed first;
// `null` when the segment never enters the expanded rect (or starts inside
// it — that case belongs to the discrete overlap pass).
function sweptBrickHit(ball, prevX, prevY, brick) {
  const left = brick.x - ball.r;
  const right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r;
  const bottom = brick.y + brick.h + ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let tMin = 0;
  let tMax = 1;
  let face = null;

  if (Math.abs(dx) < 1e-12) {
    if (prevX <= left || prevX >= right) return null;
  } else {
    let t1 = (left - prevX) / dx;
    let t2 = (right - prevX) / dx;
    let f1 = 'left';
    let f2 = 'right';
    if (t1 > t2) {
      const t = t1; t1 = t2; t2 = t;
      const f = f1; f1 = f2; f2 = f;
    }
    if (t1 > tMin) { tMin = t1; face = f1; }
    tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }

  if (Math.abs(dy) < 1e-12) {
    if (prevY <= top || prevY >= bottom) return null;
  } else {
    let t1 = (top - prevY) / dy;
    let t2 = (bottom - prevY) / dy;
    let f1 = 'top';
    let f2 = 'bottom';
    if (t1 > t2) {
      const t = t1; t1 = t2; t2 = t;
      const f = f1; f1 = f2; f2 = f;
