    if (t1 > tMin) {
      if (Math.abs(t1 - tMin) <= 1e-9) face = 'corner'; // entered on both axes at once
      else face = f1;
      tMin = t1;
    }
    tMax = Math.min(tMax, t2);
    if (tMin > tMax) return null;
  }

  if (face === null || tMin >= 1) return null;
  return { t: tMin, face };
}
